import { getActingAddress, subscribe } from '../app/store.js';
import { displayEthCompact } from '../app/scaling.js';
import { DGN_QUADRANTS, DGN_SYMBOLS, dgnBadgePath } from '../app/dgn-traits.js';
import { readDegeneretteQuickPlay, writeDegeneretteQuickPlaySymbol, DEGENERETTE_QUICKPLAY_CHANGED } from '../app/degenerette-quickplay.js';
import { lock as lockScroll, unlock as unlockScroll } from '../app/scroll-lock.js';
import { setActionFeedback } from './action-feedback.js';

export function mountDegeneretteQuickPlay(host) {
  const summary = document.createElement('button');
  summary.type = 'button';
  summary.className = 'site-degenerette-symbol';
  summary.setAttribute('aria-haspopup', 'dialog');
  summary.setAttribute('aria-controls', 'site-degenerette-symbol-dialog');
  summary.setAttribute('aria-expanded', 'false');
  const symbolImage = document.createElement('img');
  symbolImage.alt = '';
  summary.append(symbolImage);
  const button = document.createElement('button');
  button.type = 'button';
  button.className = 'site-degenerette-quickplay';
  const feedback = document.createElement('div');
  feedback.setAttribute('role', 'status');
  feedback.hidden = true;
  document.body.append(feedback);
  host.append(summary, button);
  let busy = false;
  let displayed = null;
  let dialog = null;
  let dialogOwner = null;
  let scrollLocked = false;
  const finishPicker = () => {
    if (scrollLocked) { unlockScroll(); scrollLocked = false; }
    summary.setAttribute('aria-expanded', 'false');
  };
  const closePicker = () => { dialog?.close(); finishPicker(); };
  const paint = () => {
    const owner = getActingAddress();
    if (dialog?.open && owner !== dialogOwner) closePicker();
    const bet = readDegeneretteQuickPlay(owner);
    displayed = { owner, bet };
    const total = BigInt(bet.amountPerTicketWei) * BigInt(bet.ticketCount);
    const symbol = DGN_SYMBOLS[DGN_QUADRANTS[bet.symbol >> 3]][bet.symbol & 7].toUpperCase();
    const amount = bet.currency === 0
      ? `${displayEthCompact(total, 9)} ETH`
      : `${(total / (10n ** 18n)).toLocaleString('en-US')} FLIP`;
    const symbolPath = dgnBadgePath(bet.symbol >> 3, bet.symbol & 7, null);
    if (symbolImage.getAttribute('src') !== symbolPath) symbolImage.src = symbolPath;
    summary.setAttribute('aria-label', `Change symbol: ${symbol}`);
    summary.title = `Change symbol: ${symbol}`;
    summary.disabled = busy;
    for (const choice of dialog?.querySelectorAll('[data-quickplay-symbol]') || []) {
      const selected = Number(choice.dataset.quickplaySymbol) === bet.symbol;
      choice.classList.toggle('is-selected', selected);
      choice.setAttribute('aria-pressed', String(selected));
    }
    button.textContent = busy ? 'BUYING…' : `QUICK PLAY – ${amount}`;
    button.disabled = busy || !owner;
    button.setAttribute('aria-busy', String(busy));
    button.setAttribute('aria-label', `Quick Play – ${amount} · ${symbol} · ${bet.saved ? 'repeat last manual bet' : 'default bet'}`);
    button.title = owner
      ? `${bet.saved ? 'Repeat your last confirmed manual bet' : 'Play for 1,000 FLIP'} · ${symbol}. Click the logo to customize.`
      : 'Connect your wallet and select an account to play.';
  };
  summary.addEventListener('click', () => {
    if (busy) return;
    if (!dialog) {
      dialog = document.createElement('dialog');
      dialog.id = 'site-degenerette-symbol-dialog';
      dialog.className = 'dgn-symbol-dialog';
      dialog.setAttribute('aria-labelledby', 'site-degenerette-symbol-title');
      dialog.innerHTML = `<section class="dgn-symbol-dialog__card">
        <header class="dgn-symbol-dialog__header">
          <h3 id="site-degenerette-symbol-title">Choose your symbol</h3>
          <button type="button" class="dgn-symbol-dialog__close" aria-label="Close symbol picker">×</button>
        </header>
        <div class="dgn-symbol-picker"></div>
      </section>`;
      for (let q = 0; q < 3; q++) {
        const section = document.createElement('section');
        section.className = 'dgn-symbol-group';
        const heading = document.createElement('h4');
        heading.textContent = DGN_QUADRANTS[q];
        const group = document.createElement('div');
        group.className = 'dgn-symbols';
        group.setAttribute('role', 'group');
        group.setAttribute('aria-label', `${DGN_QUADRANTS[q]} symbols`);
        for (let s = 0; s < 8; s++) {
          const symbol = (q << 3) | s;
          const choice = document.createElement('button');
          choice.type = 'button';
          choice.className = 'dgn-symbol-btn';
          choice.dataset.quickplaySymbol = String(symbol);
          const name = DGN_SYMBOLS[DGN_QUADRANTS[q]][s].toUpperCase();
          choice.setAttribute('aria-label', name);
          const badge = document.createElement('span');
          badge.className = 'dgn-symbol-badge';
          badge.dataset.badge = 'full';
          const img = document.createElement('img');
          img.src = dgnBadgePath(q, s, null);
          img.alt = '';
          img.width = img.height = 48;
          badge.append(img);
          const caption = document.createElement('span');
          caption.className = 'dgn-symbol-btn__name';
          caption.textContent = name;
          choice.append(badge, caption);
          choice.addEventListener('click', () => {
            if (getActingAddress() !== dialogOwner) { closePicker(); return; }
            if (!writeDegeneretteQuickPlaySymbol(dialogOwner, symbol)) {
              setActionFeedback(feedback, 'Could not save your symbol. Try again.');
              return;
            }
            closePicker();
          });
          group.append(choice);
        }
        section.append(heading, group);
        dialog.querySelector('.dgn-symbol-picker').append(section);
      }
      dialog.querySelector('.dgn-symbol-dialog__close').addEventListener('click', closePicker);
      dialog.addEventListener('close', () => { finishPicker(); summary.focus({ preventScroll: true }); });
      dialog.addEventListener('click', event => {
        if (event.target !== dialog) return;
        const rect = dialog.getBoundingClientRect();
        if (event.clientX < rect.left || event.clientX > rect.right || event.clientY < rect.top || event.clientY > rect.bottom) closePicker();
      });
      document.body.append(dialog);
    }
    dialogOwner = getActingAddress();
    paint();
    dialog.showModal();
    lockScroll();
    scrollLocked = true;
    summary.setAttribute('aria-expanded', 'true');
    dialog.querySelector(`[data-quickplay-symbol="${displayed.bet.symbol}"]`)?.focus();
  });
  button.addEventListener('click', async () => {
    if (busy || !displayed?.owner) return;
    const selected = displayed;
    busy = true;
    paint();
    setActionFeedback(feedback, '');
    try {
      await import('../components/app-degenerette-panel.js');
      const panel = document.querySelector('app-degenerette-panel');
      if (!panel?.quickPlayBet) throw Error('Degenerette is still loading. Try again.');
      const result = await panel.quickPlayBet(selected.owner, selected.bet);
      setActionFeedback(feedback, result?.ok ? 'Cards purchased. Watch Pending for your reveal.' : result?.message || 'Purchase was not completed.');
    } catch (error) {
      setActionFeedback(feedback, error?.message || 'Purchase was not completed.');
    } finally {
      busy = false;
      paint();
    }
  });
  for (const field of ['connected.address', 'viewing.address', 'viewing.combined', 'ui.mode']) subscribe(field, paint);
  document.addEventListener(DEGENERETTE_QUICKPLAY_CHANGED, paint);
  window.addEventListener('storage', paint);
  paint();
}
